## 4. 领域模型（`src/domain/types.ts`）

```ts
/** 金额：整数，单位为"分"。禁止小数（INV-3）。 */
export type Cents = number;

export type TxType = 'expense' | 'income';

/** 本地日期字符串 'YYYY-MM-DD'；本地月份 'YYYY-MM'（INV-4）。 */
export type DateKey = string;
export type MonthKey = string;

export interface Category {
  id: string;              // 'cat_' + uuid，内置分类 ID 固定（§6.7）
  name: string;            // 1–6 字
  icon: IconName;          // 来自内置图标集
  kind: TxType;            // 归属；支出分类不可用于收入记录
  sortOrder: number;       // 升序展示
  isBuiltin: boolean;      // 内置分类不可删除，仅可改名/排序
  archivedAt?: number;     // 归档时间戳（不物理删除的软删，见 §6.7）
}

export interface Transaction {
  id: string;              // 'tx_' + uuid
  type: TxType;
  amountCents: Cents;      // > 0，整数
  categoryId: string;
  date: DateKey;           // 归属日（用户可改，默认今天）
  note: string;            // '' 或 ≤ 50 字
  createdAt: number;       // epoch ms
  updatedAt: number;       // epoch ms
}

export interface Budget {
  month: MonthKey;         // 'YYYY-MM'
  amountCents: Cents;      // > 0
}

/** meta 表键值：settings / lastExportAt / schemaVersion 等。 */
export interface AppSettings {
  currencySymbol: '¥' | '$' | '€' | 'none';
  theme: 'system' | 'light' | 'dark';
  lastUsedCategoryId: string | null;   // US-1 默认选中
  lastExportAt: number | null;         // US-6 提醒
  onboarded: boolean;                  // 首次引导是否已看过
}

/** 领域错误：所有可预期的失败走此类型，不 throw 裸 Error。 */
export type DomainErrorCode =
  | 'INVALID_AMOUNT' | 'AMOUNT_NOT_INTEGER' | 'AMOUNT_OUT_OF_RANGE'
  | 'INVALID_DATE' | 'CATEGORY_NOT_FOUND' | 'CATEGORY_KIND_MISMATCH'
  | 'NOTE_TOO_LONG' | 'CATEGORY_IN_USE' | 'CATEGORY_NAME_DUPLICATE'
  | 'IMPORT_SCHEMA_UNSUPPORTED' | 'IMPORT_PARSE_ERROR' | 'IMPORT_VALIDATION_FAILED'
  | 'STORAGE_QUOTA_EXCEEDED' | 'STORAGE_UNAVAILABLE';

export interface DomainError {
  code: DomainErrorCode;
  message: string;                 // 面向用户的中文提示（§13）
  detail?: Record<string, unknown>; // 结构化信息（字段名、行号等）
}
```

**约束汇总**：`amountCents` 范围 `1 .. 999_999_999`（即 ≤ 999 万元），超出报 `AMOUNT_OUT_OF_RANGE`。

